def ensure_pykrx_imported() -> Any:
    global pykrx_stock, PYKRX_IMPORT_ERROR, PykrxKrxWebIo
    if pykrx_stock is not None or PYKRX_IMPORT_ERROR is not None:
        return pykrx_stock
    try:
        pykrx_stock = importlib.import_module("pykrx.stock")
        PYKRX_IMPORT_ERROR = None
    except Exception as exc:
        pykrx_stock = None
        PYKRX_IMPORT_ERROR = exc
    try:
        if PykrxKrxWebIo is None:
            PykrxKrxWebIo = getattr(importlib.import_module("pykrx.website.krx.krxio"), "KrxWebIo", None)
    except Exception:
        PykrxKrxWebIo = None
    return pykrx_stock


def ensure_telethon_imported() -> Any:
    global TelegramClient, SessionPasswordNeededError, PeerChannel
    if TelegramClient is not None:
        return TelegramClient
    TelegramClient = getattr(importlib.import_module("telethon"), "TelegramClient")
    SessionPasswordNeededError = getattr(importlib.import_module("telethon.errors"), "SessionPasswordNeededError")
    PeerChannel = getattr(importlib.import_module("telethon.tl.types"), "PeerChannel")
    return TelegramClient


