def normalize_text(value: Any) -> str:
    if value is None or (isinstance(value, float) and math.isnan(value)):
        return ""
    return re.sub(r"\s+", "", str(value).strip()).lower()


def normalize_stock_search_text(value: Any) -> str:
    text = normalize_text(value)
    if not text:
        return ""
    return re.sub(r"[\W_]+", "", text, flags=re.UNICODE)


def stock_search_aliases(value: Any) -> set[str]:
    aliases: set[str] = set()
    normalized = normalize_text(value)
    compact = normalize_stock_search_text(value)
    if normalized:
        aliases.add(normalized)
    if compact:
        aliases.add(compact)
    return aliases


def to_float(value: Any) -> float | None:
    if value is None or pd.isna(value):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def parse_korean_number(value: Any) -> float | None:
    if value is None or pd.isna(value):
        return None
    text = str(value).replace(",", "")
    match = re.search(r"-?\d+(?:\.\d+)?", text)
    if not match:
        return None
    try:
        return float(match.group(0))
    except ValueError:
        return None


def safe_copy_to_temp(source_path: Path) -> Path:
    temp_dir = Path(tempfile.gettempdir()) / "stock_dashboard_cache"
    temp_dir.mkdir(parents=True, exist_ok=True)
    temp_path = temp_dir / f"{source_path.stem}_{uuid.uuid4().hex[:8]}{source_path.suffix}"
    last_error: Exception | None = None
    for _ in range(8):
        try:
            shutil.copy2(source_path, temp_path)
            return temp_path
        except PermissionError as exc:
            last_error = exc
            time.sleep(0.4)
        except Exception:
            raise
    if last_error is not None:
        raise PermissionError(
            f"?ëÏ? ?åÏùº???§Î•∏ ?ÑÎ°ú?∏Ïä§(Excel/?ôÍ∏∞???êÏÑú ?†Í≤® ?ΩÏùÑ ???ÜÏäµ?àÎã§. "
            f"?åÏùº???´Í≥† ?§Ïãú ?úÎèÑ?òÏÑ∏?? {source_path}"
        ) from last_error
    return temp_path


def excel_engine_for_path(path: Path) -> str | None:
    suffix = path.suffix.lower()
    if suffix in {".xlsx", ".xlsm", ".xltx", ".xltm"}:
        return "openpyxl"
    if suffix == ".xls":
        return "xlrd"
    return None


def sanitize_filename(value: str) -> str:
    cleaned = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "_", value).strip(" .")
    return cleaned or "attachment"


def parse_date_label(value: Any) -> datetime | None:
    if value is None or pd.isna(value):
        return None
    match = re.search(r"(\d{4})[./-](\d{2})[./-](\d{2})", str(value))
    if not match:
        return None
    return datetime.strptime("-".join(match.groups()), "%Y-%m-%d")


def parse_iso_datetime(value: Any) -> datetime | None:
    try:
        if not value:
            return None
        parsed = datetime.fromisoformat(str(value))
        if parsed.tzinfo is not None:
            parsed = parsed.astimezone().replace(tzinfo=None)
        return parsed
    except Exception:
        return None


def load_settings() -> dict[str, Any]:
    if SETTINGS_PATH.exists():
        return json.loads(SETTINGS_PATH.read_text(encoding="utf-8-sig"))
    return {}


def save_settings(settings: dict[str, Any]) -> None:
    SETTINGS_PATH.parent.mkdir(parents=True, exist_ok=True)
    SETTINGS_PATH.write_text(json.dumps(settings, ensure_ascii=False, indent=2), encoding="utf-8")


