def screening_data_version_token() -> str:
    # ?êÏàò ?¨Í≥Ñ??SQL Í∞±Ïã†) ??DB mtime??Î∞îÎÄåÎ?Î°?Ï∫êÏãú ?§Î? ?êÎèô Î¨¥Ìö®?îÌïú??
    try:
        if SCREENING_FAST_DB_PATH.exists():
            return f"db{int(SCREENING_FAST_DB_PATH.stat().st_mtime)}"
    except Exception:
        pass
    try:
        files = sorted(
            (p for p in SCREENING_DIR.glob("*.xls*") if re.match(r"^(20\d{6})_", p.name)),
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )
        if files:
            return f"xlsx{int(files[0].stat().st_mtime)}"
    except Exception:
        pass
    return "na"


def screening_cache_key(file_date: str, min_score: float) -> str:
    token = screening_data_version_token()
    return f"{SCREENING_SCORE_CACHE_VERSION}|{token}|{file_date}|{float(min_score):.4f}"


def screening_summary_payload_cache_key(file_date: str, min_score: float, recent_limit: int, universe: str = "stock") -> str:
    token = screening_data_version_token()
    normalized_universe = "etf" if str(universe or "").strip().lower() == "etf" else "stock"
    return f"{SCREENING_SCORE_CACHE_VERSION}|payload|{token}|{file_date}|{float(min_score):.4f}|{int(recent_limit)}|{normalized_universe}"


def screening_payload_file_name(file_date: str, recent_limit: int, universe: str = "stock", lite: bool = False) -> str:
    normalized_universe = normalize_kr_screening_universe(universe)
    mode = "lite" if lite else "full"
    safe_date = re.sub(r"[^0-9-]", "", str(file_date or "").strip()) or "unknown"
    # Payloads are invalidated explicitly after score recalculation. Keeping the
    # key date-scoped prevents one newly inserted trading day from invalidating
    # every historical response through the database mtime.
    return f"v{SCREENING_SCORE_CACHE_VERSION}_{safe_date}_{normalized_universe}_{mode}_r{int(recent_limit)}.json"


def screening_payload_file_path(file_date: str, recent_limit: int, universe: str = "stock", lite: bool = False) -> Path:
    return SCREENING_PAYLOAD_CACHE_DIR / screening_payload_file_name(file_date, recent_limit, universe=universe, lite=lite)


def screening_payload_file_exists(file_date: str, recent_limit: int, universe: str = "stock", lite: bool = False) -> bool:
    path = screening_payload_file_path(file_date, recent_limit, universe=universe, lite=lite)
    if path.exists():
        return True
    normalized_universe = normalize_kr_screening_universe(universe)
    mode = "lite" if lite else "full"
    safe_date = re.sub(r"[^0-9-]", "", str(file_date or "").strip()) or "unknown"
    legacy_pattern = (
        f"v{SCREENING_SCORE_CACHE_VERSION}_*_{safe_date}_{normalized_universe}_{mode}_r{int(recent_limit)}.json"
    )
    return next(SCREENING_PAYLOAD_CACHE_DIR.glob(legacy_pattern), None) is not None


def load_screening_payload_file(file_date: str, recent_limit: int, universe: str = "stock", lite: bool = False) -> dict[str, Any] | None:
    path = screening_payload_file_path(file_date, recent_limit, universe=universe, lite=lite)
    if not path.exists():
        normalized_universe = normalize_kr_screening_universe(universe)
        mode = "lite" if lite else "full"
        safe_date = re.sub(r"[^0-9-]", "", str(file_date or "").strip()) or "unknown"
        legacy_pattern = (
            f"v{SCREENING_SCORE_CACHE_VERSION}_*_{safe_date}_{normalized_universe}_{mode}_r{int(recent_limit)}.json"
        )
        legacy_paths = sorted(
            SCREENING_PAYLOAD_CACHE_DIR.glob(legacy_pattern),
            key=lambda item: item.stat().st_mtime_ns,
            reverse=True,
        )
        if not legacy_paths:
            return None
        path = legacy_paths[0]
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    stable_path = screening_payload_file_path(file_date, recent_limit, universe=universe, lite=lite)
    if path != stable_path:
        try:
            save_screening_payload_file(payload, file_date, recent_limit, universe=universe, lite=lite)
        except Exception:
            pass
    return payload


def save_screening_payload_file(payload: dict[str, Any], file_date: str, recent_limit: int, universe: str = "stock", lite: bool = False) -> None:
    SCREENING_PAYLOAD_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    path = screening_payload_file_path(file_date, recent_limit, universe=universe, lite=lite)
    temp_path = path.with_name(f"{path.stem}_{uuid.uuid4().hex[:8]}.tmp")
    # Date payloads are read by the API, not edited by hand. Compact JSON cuts
    # historical cache disk I/O substantially without changing the response.
    temp_path.write_text(
        json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
        encoding="utf-8",
    )
    temp_path.replace(path)


def clear_screening_payload_file_cache(file_dates: list[str] | tuple[str, ...] | None = None) -> None:
    if not SCREENING_PAYLOAD_CACHE_DIR.exists():
        return
    normalized_dates = {
        f"{digits[:4]}-{digits[4:6]}-{digits[6:]}"
        for value in (file_dates or [])
        for digits in [re.sub(r"\D", "", str(value or ""))]
        if len(digits) == 8
    }
    for path in SCREENING_PAYLOAD_CACHE_DIR.glob("*.json"):
        if normalized_dates and not any(f"_{date_text}_" in path.name for date_text in normalized_dates):
            continue
        try:
            path.unlink()
        except Exception:
            pass


def parse_screening_cache_key(key: Any) -> tuple[str, str]:
    parts = str(key).split("|")
    if len(parts) == 4 and parts[0] == SCREENING_SCORE_CACHE_VERSION:
        return parts[2], parts[3]
    if len(parts) == 3 and parts[0] == SCREENING_SCORE_CACHE_VERSION:
        # legacy format fallback
        return parts[1], parts[2]
    return "", ""


def normalize_kr_screening_universe(universe: str | None) -> str:
    return "etf" if str(universe or "").strip().lower() == "etf" else "stock"


def filter_kr_screening_rows_by_universe(rows: list[dict[str, Any]], universe: str = "stock") -> list[dict[str, Any]]:
    normalized_universe = normalize_kr_screening_universe(universe)
    filtered: list[dict[str, Any]] = []
    for row in (rows or []):
        if not isinstance(row, dict):
            continue
        is_etf = bool(
            str(row.get("security_type") or "").strip().lower() == "etf"
            or is_kr_etf_stock_code(row.get("stock_code"))
        )
        if normalized_universe == "etf":
            if not is_etf:
                continue
        else:
            if is_etf:
                continue
        filtered.append(dict(row))
    for index_no, row in enumerate(filtered, start=1):
        row["rank"] = index_no
    return filtered


def build_theme_summary_records(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    theme_df = pd.DataFrame(rows)
    if theme_df.empty:
        return []
    grouped = (
        theme_df.groupby("theme", as_index=False)
        .agg(
            count=("stock_name", "count"),
            avg_score=("score", "mean"),
            max_score=("score", "max"),
            leaders=("stock_name", lambda items: ", ".join(list(items)[:5])),
            keywords=("theme_keywords", lambda items: ", ".join(sorted({token for sub in items for token in sub if token})[:5])),
        )
        .sort_values(["count", "avg_score", "max_score"], ascending=[False, False, False])
        .head(15)
    )
    grouped["avg_score"] = grouped["avg_score"].round(2)
    grouped["max_score"] = grouped["max_score"].round(2)
    return grouped.to_dict(orient="records")


