def fetch_kr_etf_snapshot(code: str) -> dict[str, Any]:
    normalized_code = str(code or "").strip()
    item = kr_etf_item_map().get(normalized_code) or {"code": normalized_code, "name": normalized_code, "theme": ""}
    listing_item = kr_etf_listing_map().get(normalized_code) or {}
    cache_key = f"kr_etf:{normalized_code}"
    cached = ETF_FLOW_SNAPSHOT_CACHE.get(cache_key)
    now_ts = time.time()
    if cached and (now_ts - cached[0]) <= ETF_FLOW_CACHE_TTL_SECONDS:
        return dict(cached[1])
    holdings: list[dict[str, Any]] = []
    assets_text = ""
    assets_value = to_float(listing_item.get("aum"))
    source_parts: list[str] = []
    try:
        url = f"https://stockanalysis.com/quote/krx/{quote(normalized_code)}/holdings/"
        response = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=15)
        if response.ok:
            html = response.text
            holdings = extract_stockanalysis_holdings(html, "KR")
            assets_match = re.search(r"Assets\s*<div class=\"mt-0\.5 text-lg font-semibold bp:text-xl sm:mt-1\.5 sm:text-2xl\">([^<]+)<", html)
            assets_text = assets_match.group(1).strip() if assets_match else ""
            assets_value = parse_compact_number(assets_text, "KRW") or assets_value
            source_parts.append("StockAnalysis")
    except Exception:
        pass

    flow = {"value": None, "text": "", "source": "TradingView"}
    try:
        flow = fetch_tradingview_etf_flow_1y(f"KRX-{normalized_code}", "KRW")
        source_parts.append("TradingView")
    except Exception:
        pass

    tracking_index_name = kr_etf_tracking_index_name(
        normalized_code,
        item.get("theme") or listing_item.get("name") or "",
    )
    if not assets_text and assets_value:
        assets_text = ""
    if listing_item:
        source_parts.append("FinanceDataReader")
    payload = {
        "market": "KR",
        "symbol": normalized_code,
        "name": item.get("name") or listing_item.get("name") or normalized_code,
        "theme": tracking_index_name,
        "tracking_index_name": tracking_index_name,
        "currency": "KRW",
        "aum": assets_value,
        "aum_text": assets_text,
        "flow_1y": flow.get("value"),
        "flow_1y_text": flow.get("text") or "",
        "holdings": holdings,
        "holding_count": len(holdings),
        "source": " + ".join(dict.fromkeys([part for part in source_parts if part])) or "Í∏∞Î≥∏ ?ïÎ≥¥",
    }
    ETF_FLOW_SNAPSHOT_CACHE[cache_key] = (now_ts, payload)
    return dict(payload)


def fetch_us_etf_snapshot(symbol: str) -> dict[str, Any]:
    normalized_symbol = normalize_global_symbol(symbol)
    item = us_etf_item_map().get(normalized_symbol) or {"symbol": normalized_symbol, "name": normalized_symbol, "theme": "", "tv_symbol": f"AMEX-{normalized_symbol}"}
    cache_key = f"us_etf:{normalized_symbol}"
    cached = ETF_FLOW_SNAPSHOT_CACHE.get(cache_key)
    now_ts = time.time()
    if cached and (now_ts - cached[0]) <= ETF_FLOW_CACHE_TTL_SECONDS:
        return dict(cached[1])
    ticker = yf.Ticker(normalized_symbol)
    holdings_df = ticker.funds_data.top_holdings
    holdings: list[dict[str, Any]] = []
    if holdings_df is not None and not holdings_df.empty:
        for index_value, row in holdings_df.reset_index().iterrows():
            row_symbol = normalize_global_symbol(row.get("Symbol") or row.get("symbol") or row.get("index") or "")
            row_name = str(row.get("Name") or row.get("name") or row_symbol).strip()
            weight_value = to_float(row.get("Holding Percent"))
            if not row_symbol or weight_value is None:
                continue
            holdings.append(
                {
                    "rank": int(index_value) + 1,
                    "symbol": row_symbol,
                    "name": row_name,
                    "weight_pct": float(weight_value) * 100.0,
                    "shares": None,
                }
            )
    info = ticker.info or {}
    aum_value = to_float(info.get("totalAssets")) or to_float(info.get("netAssets")) or to_float(info.get("marketCap"))
    flow = fetch_tradingview_etf_flow_1y(item.get("tv_symbol") or f"AMEX-{normalized_symbol}", "USD")
    payload = {
        "market": "US",
        "symbol": normalized_symbol,
        "name": item.get("name") or normalized_symbol,
        "theme": item.get("theme") or "",
        "currency": "USD",
        "aum": aum_value,
        "aum_text": "",
        "flow_1y": flow.get("value"),
        "flow_1y_text": flow.get("text") or "",
        "holdings": holdings,
        "holding_count": len(holdings),
        "source": "yfinance + TradingView",
    }
    ETF_FLOW_SNAPSHOT_CACHE[cache_key] = (now_ts, payload)
    return dict(payload)


def search_etf_flow_assets(query: str, limit: int = 12) -> list[dict[str, Any]]:
    raw_query = str(query or "").strip()
    if not raw_query:
        return []
    items: list[dict[str, Any]] = []
    for item in autocomplete_stocks(raw_query, limit=max(4, min(limit, 12))):
        code = str(item.get("code") or "").zfill(6)
        items.append(
            {
                "id": f"kr_stock:{code}",
                "kind": "kr_stock",
                "value": code,
                "symbol": code,
                "name": str(item.get("name") or code).strip(),
                "market": str(item.get("market") or "").strip(),
                "label": "Íµ?Ç¥",
            }
        )
    for item in search_global_companies(raw_query, limit=max(4, min(limit, 10))):
        symbol = normalize_global_symbol(item.get("symbol") or "")
        name = str(item.get("name") or symbol).strip()
        market = str(item.get("exchange") or "US").strip() or "US"
        if not symbol:
            continue
        if market and market.upper() not in {"US", "NASDAQ", "NYSE", "NYSEARCA", "AMEX", "NMS", "NYQ"}:
            continue
        if symbol in us_etf_item_map() or re.search(r"\b(ETF|Trust|Fund)\b", name, re.I):
            continue
        if re.search(r"\b(Shares|Bull|Bear|Ultra|ProShares|Direxion)\b", name, re.I):
            continue
        items.append(
            {
                "id": f"global_stock:{symbol}",
                "kind": "global_stock",
                "value": symbol,
                "symbol": symbol,
                "name": name,
                "market": market,
                "label": "ÎØ∏Íµ≠",
            }
        )
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in items:
        item_id = str(item.get("id") or "").strip()
        if not item_id or item_id in seen:
            continue
        seen.add(item_id)
        deduped.append(item)
        if len(deduped) >= limit:
            break
    return deduped


def build_etf_flow_payload(kind: str, value: str, name: str = "") -> dict[str, Any]:
    asset = build_correlation_asset_summary(kind, value, name=name)
    normalized_kind = str(asset.get("kind") or kind or "").strip().lower()
    if normalized_kind not in {"kr_stock", "global_stock"}:
        raise ValueError("ETF ?êÍ∏à Ï∂îÏ†ï?Ä Íµ?Ç¥/ÎØ∏Íµ≠ Í∞úÎ≥Ñ Ï¢ÖÎ™©Îß?ÏßÄ?êÌï©?àÎã§.")
    if normalized_kind == "kr_stock":
        universe = [("KR", str(code or "").strip()) for code, _, _ in KOREA_STOCK_ETF_ITEMS]
        target_symbol = normalize_stock_code_value(asset.get("symbol") or asset.get("value") or value)
    else:
        universe = [("US", normalize_global_symbol(item.get("symbol") or "")) for item in US_STOCK_ETF_ITEMS]
        target_symbol = normalize_global_symbol(asset.get("symbol") or asset.get("value") or value)
    rows: list[dict[str, Any]] = []
    failures: list[str] = []

    def load_snapshot(entry: tuple[str, str]) -> dict[str, Any]:
        market, symbol = entry
        if market == "KR":
            return fetch_kr_etf_snapshot(symbol)
        return fetch_us_etf_snapshot(symbol)

    with ThreadPoolExecutor(max_workers=min(10, max(4, len(universe)))) as executor:
        future_map = {executor.submit(load_snapshot, entry): entry for entry in universe}
        for future in as_completed(future_map):
            market, etf_symbol = future_map[future]
            try:
                snapshot = future.result()
            except Exception as exc:
                failures.append(f"{market}:{etf_symbol}:{exc}")
                continue
            for holding in snapshot.get("holdings") or []:
                holding_symbol = normalize_stock_code_value(holding.get("symbol")) if market == "KR" else normalize_global_symbol(holding.get("symbol"))
                if holding_symbol != target_symbol:
                    continue
                weight_pct = float(to_float(holding.get("weight_pct")) or 0.0)
                aum_value = to_float(snapshot.get("aum"))
                flow_value = to_float(snapshot.get("flow_1y"))
                exposure_value = aum_value * weight_pct / 100.0 if aum_value is not None else None
                estimated_flow = flow_value * weight_pct / 100.0 if flow_value is not None else None
                rows.append(
                    {
                        "etf_symbol": snapshot.get("symbol") or etf_symbol,
                        "etf_name": snapshot.get("name") or etf_symbol,
                        "theme": snapshot.get("theme") or "",
                        "currency": snapshot.get("currency") or ("KRW" if market == "KR" else "USD"),
                        "weight_pct": round(weight_pct, 4),
                        "aum": aum_value,
                        "aum_text": snapshot.get("aum_text") or "",
                        "flow_1y": flow_value,
                        "estimated_stock_flow_1y": estimated_flow,
                        "holding_exposure": exposure_value,
                        "holding_rank": holding.get("rank"),
                        "source": snapshot.get("source") or "",
                    }
                )
                break
    rows.sort(
        key=lambda row: (
            -(abs(float(row.get("estimated_stock_flow_1y") or 0.0))),
            -(float(row.get("holding_exposure") or 0.0)),
            str(row.get("etf_symbol") or ""),
        )
    )
    matched_rows = len(rows)
    total_estimated_flow = sum(float(row.get("estimated_stock_flow_1y") or 0.0) for row in rows if row.get("estimated_stock_flow_1y") is not None)
    total_exposure = sum(float(row.get("holding_exposure") or 0.0) for row in rows if row.get("holding_exposure") is not None)
    flow_available_count = sum(1 for row in rows if row.get("estimated_stock_flow_1y") is not None)
    return {
        "asset": asset,
        "market_scope": "KR" if normalized_kind == "kr_stock" else "US",
        "as_of": date.today().isoformat(),
        "tracked_etf_count": len(universe),
        "matched_etf_count": matched_rows,
        "flow_available_count": flow_available_count,
        "total_estimated_stock_flow_1y": total_estimated_flow if flow_available_count else None,
        "total_holding_exposure": total_exposure if matched_rows else None,
        "rows": rows,
        "coverage_note": "?Ä??ETF Î∞îÏä§Ïº?Í∏∞Ï? Ï∂îÏ†ï?ÖÎãà?? 1??ETF ?ÑÏ†Å ?úÏú†?ÖÍ≥º ?ÑÏû¨ ?∏ÏûÖ ÎπÑÏ§ë??Í≥±Ìï¥ Ï¢ÖÎ™©Î≥??ÅÌñ•????Ç∞?©Îãà??",
        "failures": failures[:20],
    }


