def build_global_company_earnings_call_text(brief: dict[str, Any], call_info: dict[str, Any]) -> str:
    lines: list[str] = []
    headline = str(brief.get("headline") or call_info.get("title") or "").strip()
    if headline:
        lines.append(headline)
    summary_points = brief.get("summary_points") if isinstance(brief.get("summary_points"), list) else []
    if summary_points:
        lines.append("")
        lines.append("[?µÏã¨ ?îÏïΩ]")
        lines.extend(f"- {str(item).strip()}" for item in summary_points if str(item).strip())
    management_messages = brief.get("management_messages") if isinstance(brief.get("management_messages"), list) else []
    if management_messages:
        lines.append("")
        lines.append("[Í≤ΩÏòÅÏß?Î©îÏãúÏßÄ]")
        lines.extend(f"- {str(item).strip()}" for item in management_messages if str(item).strip())
    watch_points = brief.get("watch_points") if isinstance(brief.get("watch_points"), list) else []
    if watch_points:
        lines.append("")
        lines.append("[Ï≤¥ÌÅ¨ ?¨Ïù∏??")
        lines.extend(f"- {str(item).strip()}" for item in watch_points if str(item).strip())
    translated_preview = str(brief.get("translated_preview") or "").strip()
    if translated_preview:
        lines.append("")
        lines.append("[Î≤àÏó≠ ÎØ∏Î¶¨Î≥¥Í∏∞]")
        lines.append(translated_preview)
    note = str(brief.get("note") or "").strip()
    if note:
        lines.append("")
        lines.append(f"[ÎπÑÍ≥†] {note}")
    return "\n".join(lines).strip()


def scrape_earningscalls_page_summary(soup: BeautifulSoup) -> str:
    heading = soup.find("h2", string=re.compile(r"key takeaways", re.IGNORECASE))
    if heading is not None:
        paragraph = heading.find_next("p")
        if paragraph is not None:
            return " ".join(paragraph.get_text(" ", strip=True).split())
    for heading in soup.find_all("h2"):
        heading_text = " ".join(heading.get_text(" ", strip=True).split())
        if heading_text.endswith("?"):
            paragraph = heading.find_next("p")
            if paragraph is not None:
                return " ".join(paragraph.get_text(" ", strip=True).split())
    return ""


def scrape_earningscalls_page_topics(soup: BeautifulSoup) -> list[str]:
    topics: list[str] = []
    seen: set[str] = set()
    for heading in soup.find_all("h3"):
        text = " ".join(heading.get_text(" ", strip=True).split())
        if not text or not text.endswith("?"):
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        topics.append(text)
    return topics[:8]


def scrape_earningscalls_reported_metrics(soup: BeautifulSoup) -> list[dict[str, str]]:
    table = None
    heading = soup.find(["h2", "h3"], string=re.compile(r"reported metrics", re.IGNORECASE))
    if heading is not None:
        table = heading.find_next("table")
    if table is None:
        table = soup.find("table")
    if table is None:
        return []
    rows: list[dict[str, str]] = []
    for tr in table.find_all("tr"):
        cells = tr.find_all(["th", "td"])
        values = [" ".join(cell.get_text(" ", strip=True).split()) for cell in cells]
        if len(values) < 2:
            continue
        if values[0].strip().lower() in {"metric", "metrics"}:
            continue
        beat_miss = ""
        lowered = f"{values[1]} {' '.join(values[2:])}".lower()
        if "(beat)" in lowered or " beat" in lowered:
            beat_miss = "beat"
        elif "(miss)" in lowered or " miss" in lowered:
            beat_miss = "miss"
        elif "(positive)" in lowered:
            beat_miss = "positive"
        elif "(negative)" in lowered:
            beat_miss = "negative"
        rows.append(
            {
                "metric": values[0],
                "value": re.sub(r"\s*\((?:beat|miss|positive|negative|neutral)\)\s*", "", values[1], flags=re.IGNORECASE).strip(),
                "consensus": "",
                "beat_miss": beat_miss,
                "qoq": "",
                "yoy": "",
                "context": values[2] if len(values) > 2 else "",
            }
        )
    return rows[:8]


def build_earnings_call_financial_snapshot(detail: dict[str, Any]) -> dict[str, Any]:
    quarters = [item for item in (detail.get("quarters") or []) if isinstance(item, dict)]
    latest = quarters[0] if quarters else {}
    previous = quarters[1] if len(quarters) > 1 else {}
    year_ago = quarters[4] if len(quarters) > 4 else {}
    stats = detail.get("stats") if isinstance(detail.get("stats"), dict) else {}
    return {
        "latest_quarter": str(latest.get("label") or ""),
        "previous_quarter": str(previous.get("label") or ""),
        "year_ago_quarter": str(year_ago.get("label") or ""),
        "revenue": to_float(latest.get("revenue")),
        "revenue_prev_q": to_float(previous.get("revenue")),
        "revenue_year_ago": to_float(year_ago.get("revenue")),
        "operating_income": to_float(latest.get("operating_income")),
        "operating_income_prev_q": to_float(previous.get("operating_income")),
        "operating_income_year_ago": to_float(year_ago.get("operating_income")),
        "net_income": to_float(latest.get("net_income")),
        "net_income_prev_q": to_float(previous.get("net_income")),
        "net_income_year_ago": to_float(year_ago.get("net_income")),
        "gross_margin_pct": to_float(stats.get("gross_margin_pct")),
        "operating_margin_pct": to_float(stats.get("operating_margin_pct")),
        "net_margin_pct": to_float(stats.get("net_margin_pct")),
    }


def parse_earningscalls_sitemap_index(limit: int = 6) -> list[str]:
    response = requests.get("https://earningscalls.dev/sitemap.xml", timeout=30)
    response.raise_for_status()
    items: list[tuple[str, str]] = []
    root = BeautifulSoup(response.text, "xml")
    for sitemap in root.find_all("sitemap"):
        loc_node = sitemap.find("loc")
        lastmod_node = sitemap.find("lastmod")
        loc = str(loc_node.get_text(strip=True) if loc_node else "").strip()
        lastmod = str(lastmod_node.get_text(strip=True) if lastmod_node else "").strip()
        if "/sitemaps/transcripts-" not in loc:
            continue
        items.append((lastmod, loc))
    items.sort(reverse=True)
    return [loc for _lastmod, loc in items[: max(1, limit)]]


def find_latest_earningscalls_transcript_url(symbol: str, months_to_scan: int = 8) -> dict[str, str]:
    normalized_symbol = normalize_global_symbol(symbol)
    ticker = normalized_symbol.split(".", 1)[0].strip().lower()
    if not ticker:
        raise LookupError("?†Ìö®???∞Ïª§Î•?Ï∞æÏ? Î™ªÌñà?µÎãà??")
    candidate_rows: list[dict[str, str]] = []
    seen_urls: set[str] = set()
    for sitemap_url in parse_earningscalls_sitemap_index(limit=months_to_scan):
        try:
            response = requests.get(sitemap_url, timeout=30)
            response.raise_for_status()
            root = BeautifulSoup(response.text, "xml")
        except Exception:
            continue
        for url_node in root.find_all("url"):
            loc_node = url_node.find("loc")
            lastmod_node = url_node.find("lastmod")
            loc = str(loc_node.get_text(strip=True) if loc_node else "").strip()
            if not loc or loc in seen_urls:
                continue
            if f"_{ticker}_earnings_call_transcript_" not in loc.lower():
                continue
            seen_urls.add(loc)
            lastmod = str(lastmod_node.get_text(strip=True) if lastmod_node else "").strip()
            candidate_rows.append({"url": loc, "lastmod": lastmod})
        if candidate_rows:
            break
    if not latest_leader_rows:
        raise LookupError("earningscalls.dev Í≥µÍ∞ú ?òÏù¥ÏßÄ?êÏÑú ÏµúÍ∑º ?§Ï†Å/Ïª®ÏΩú transcriptÎ•?Ï∞æÏ? Î™ªÌñà?µÎãà??")
    candidate_rows.sort(key=lambda item: (str(item.get("lastmod") or ""), str(item.get("url") or "")), reverse=True)
    return candidate_rows[0]


def scrape_earningscalls_transcript_page(url: str, symbol: str) -> dict[str, Any]:
    response = requests.get(url, timeout=40)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")
    title_node = soup.find("h1")
    title = " ".join(title_node.get_text(" ", strip=True).split()) if title_node else ""
    page_date = ""
    if title_node is not None:
        next_tag = title_node.find_next(["p", "time", "div"])
        if next_tag is not None:
            page_date = " ".join(next_tag.get_text(" ", strip=True).split())
    speaker_heading = soup.find(lambda tag: tag.name in {"h2", "h3"} and "speaker segments" in tag.get_text(" ", strip=True).lower())
    segments: list[dict[str, str]] = []
    if speaker_heading is not None:
        for heading in speaker_heading.find_all_next("h3"):
            previous_h2 = heading.find_previous("h2")
            if previous_h2 is not speaker_heading:
                break
            speaker = " ".join(heading.get_text(" ", strip=True).split())
            paragraph = heading.find_next("p")
            text = ""
            if paragraph is not None:
                text = " ".join(paragraph.get_text(" ", strip=True).split())
            if speaker and text:
                segments.append({"speaker": speaker, "text": text})
    cleaned_segments = []
    for item in segments:
        speaker = str(item.get("speaker") or "").strip()
        text = str(item.get("text") or "").strip()
        if not speaker or not text:
            continue
        cleaned_segments.append({"speaker": speaker, "text": text})
    if not cleaned_segments:
        raise LookupError("earningscalls.dev transcript ?òÏù¥ÏßÄ?êÏÑú Î∞úÏñ∏ Íµ¨Í∞Ñ??Ï∂îÏ∂ú?òÏ? Î™ªÌñà?µÎãà??")
    ticker = normalize_global_symbol(symbol).split(".", 1)[0]
    return {
        "ticker": ticker,
        "title": title,
        "event_date_time": page_date,
        "transcript_url": url,
        "page_summary": scrape_earningscalls_page_summary(soup),
        "page_topics": scrape_earningscalls_page_topics(soup),
        "reported_metrics": scrape_earningscalls_reported_metrics(soup),
        "speaker_segments": cleaned_segments,
    }


def build_global_company_earnings_call(symbol: str, force_refresh: bool = False) -> dict[str, Any]:
    normalized_symbol = normalize_global_symbol(symbol)
    if not normalized_symbol:
        raise ValueError("Í≤Ä?âÌï† ?∞Ïª§Î•??ÖÎ†•??Ï£ºÏÑ∏??")
    cache = load_global_company_earnings_call_cache()
    cache_key = global_company_earnings_call_cache_key(normalized_symbol)
    cached = cache.setdefault("items", {}).get(cache_key)
    if not force_refresh and isinstance(cached, dict):
        return cached

    detail = build_global_company_detail(normalized_symbol)
    transcript_ref = find_latest_earningscalls_transcript_url(normalized_symbol)
    call_info = scrape_earningscalls_transcript_page(str(transcript_ref.get("url") or ""), normalized_symbol)
    transcript_preview = "\n\n".join(
        f"{segment.get('speaker')}: {segment.get('text')}"
        for segment in (call_info.get("speaker_segments") or [])[:12]
        if isinstance(segment, dict)
    ).strip()
    summary_text = "\n".join(
        str(segment.get("text") or "").strip()
        for segment in (call_info.get("speaker_segments") or [])[:4]
        if isinstance(segment, dict) and str(segment.get("text") or "").strip()
    ).strip()
    brief = request_gemini_global_company_earnings_call_brief(
        {
            "symbol": normalized_symbol,
            "company_name": detail.get("name") or normalized_symbol,
            "event_date_time": call_info.get("event_date_time"),
            "title": call_info.get("title"),
            "page_summary": call_info.get("page_summary"),
            "page_topics": call_info.get("page_topics"),
            "reported_metrics": call_info.get("reported_metrics"),
            "financial_snapshot": build_earnings_call_financial_snapshot(detail),
            "summary_text": summary_text,
            "transcript_preview": transcript_preview,
            "transcript_url": call_info.get("transcript_url"),
        }
    )
    row_text = build_global_company_earnings_call_text(brief, call_info)
    row = {
        "chat_id": "earningscalls.dev",
        "chat_name": "earningscalls.dev",
        "message_id": hashlib.sha1(str(call_info.get("transcript_url") or "").encode("utf-8")).hexdigest()[:16],
        "date": call_info.get("event_date_time") or "",
        "text": row_text,
        "has_file": False,
        "file_name": "",
        "attachment_url": "",
        "links": [call_info.get("transcript_url")] if call_info.get("transcript_url") else [],
        "matched_keywords": [normalized_symbol, "earnings call"],
    }
    payload = {
        "symbol": normalized_symbol,
        "provider": "earningscalls.dev",
        "company_name": detail.get("name") or normalized_symbol,
        "call": call_info,
        "brief": brief,
        "raw": {
            "page_summary": call_info.get("page_summary") or "",
            "page_topics": call_info.get("page_topics") or [],
            "reported_metrics": call_info.get("reported_metrics") or [],
            "summary_text": summary_text,
            "transcript_preview": transcript_preview,
        },
        "rows": [row],
        "cached_at": datetime.now().isoformat(timespec="seconds"),
    }
    cache["items"][cache_key] = payload
    save_global_company_earnings_call_cache(cache)
    return payload


