def load_strategy_benchmark_close_map(index_key: str, start_date: date, end_date: date) -> dict[str, float]:
    mapping = {"KS11": "1001", "KQ11": "2001"}

    def close_map_from_frame(frame: pd.DataFrame, close_col_hint: str | None = None) -> dict[str, float]:
        if frame is None or frame.empty:
            return {}
        working = frame.reset_index()
        date_col = "Date" if "Date" in working.columns else working.columns[0]
        close_col = close_col_hint if close_col_hint and close_col_hint in working.columns else None
        if close_col is None:
            close_col = "Close" if "Close" in working.columns else ("Ï¢ÖÍ?" if "Ï¢ÖÍ?" in working.columns else working.columns[-1])
        output: dict[str, float] = {}
        for _, row in working.iterrows():
            dt = pd.to_datetime(row.get(date_col), errors="coerce")
            close_val = to_float(row.get(close_col))
            if pd.isna(dt) or close_val in (None, 0):
                continue
            output[dt.date().isoformat()] = float(close_val)
        return output

    if index_key in {"US500", "IXIC", "NDX100"}:
        symbol = "QQQ" if index_key == "NDX100" else str((STRATEGY_INDEXES.get(index_key) or {}).get("symbol") or "").strip()
        if not symbol:
            return {}
        try:
            frame = load_global_index_price_frame(symbol, start_date, end_date)
            return close_map_from_frame(frame, close_col_hint="Close")
        except Exception:
            return {}

    if index_key not in mapping:
        return {}

    if pykrx_stock is not None:
        try:
            frame = pykrx_stock.get_index_ohlcv_by_date(
                start_date.strftime("%Y%m%d"),
                end_date.strftime("%Y%m%d"),
                mapping[index_key],
            )
            output = close_map_from_frame(frame, close_col_hint="Ï¢ÖÍ?")
            if output:
                return output
        except Exception:
            pass

    # Offline-safe fallback: build a synthetic broad-market close series from
    # the locally cached screening DB using market-cap weighted daily returns.
    market_name = {"KS11": "KOSPI", "KQ11": "KOSDAQ"}.get(index_key)
    if market_name and SCREENING_FAST_DB_PATH.exists():
        try:
            market_codes: set[str] = set()
            try:
                listing = get_listing_table()
                market_codes = {
                    str(row.get("Code") or "").strip().zfill(6)
                    for _, row in listing.iterrows()
                    if str(row.get("Market") or "").strip().upper() == market_name
                }
            except Exception:
                market_codes = set()
            if not market_codes:
                cache = load_screening_cache()
                for summary in (cache.get("summaries") or {}).values():
                    for row in summary.get("qualified_stocks") or []:
                        code = str(row.get("stock_code") or "").strip().zfill(6)
                        market_text = str(row.get("market") or "").strip().upper()
                        if not code or not market_text:
                            continue
                        if market_name == "KOSPI" and market_text == "KOSPI":
                            market_codes.add(code)
                        elif market_name == "KOSDAQ" and market_text.startswith("KOSDAQ"):
                            market_codes.add(code)
            if market_codes:
                with sqlite3.connect(str(SCREENING_FAST_DB_PATH)) as conn:
                    rows = conn.execute(
                        """
                        SELECT file_date_key, stock_code, market_cap_100m, change_pct
                        FROM screening_rows
                        WHERE file_date_key BETWEEN ? AND ?
                        ORDER BY file_date_key ASC, stock_code ASC
                        """,
                        (start_date.strftime("%Y%m%d"), end_date.strftime("%Y%m%d")),
                    ).fetchall()
                weighted_returns: dict[str, tuple[float, float]] = {}
                for file_date_key, stock_code, market_cap_100m, change_pct in rows:
                    code = str(stock_code or "").strip().zfill(6)
                    if code not in market_codes:
                        continue
                    weight = to_float(market_cap_100m)
                    daily_change_pct = to_float(change_pct)
                    if weight is None or weight <= 0 or daily_change_pct is None:
                        continue
                    numer, denom = weighted_returns.get(str(file_date_key or ""), (0.0, 0.0))
                    numer += float(weight) * (float(daily_change_pct) / 100.0)
                    denom += float(weight)
                    weighted_returns[str(file_date_key or "")] = (numer, denom)
                ordered_keys = sorted(key for key in weighted_returns.keys() if re.match(r"^\d{8}$", key))
                if ordered_keys:
                    close_map: dict[str, float] = {}
                    level = 100.0
                    first_key = ordered_keys[0]
                    close_map[f"{first_key[:4]}-{first_key[4:6]}-{first_key[6:8]}"] = level
                    for date_key in ordered_keys[1:]:
                        numer, denom = weighted_returns.get(date_key, (0.0, 0.0))
                        daily_return = float(numer / denom) if denom else 0.0
                        if not np.isfinite(daily_return):
                            daily_return = 0.0
                        level *= 1.0 + daily_return
                        close_map[f"{date_key[:4]}-{date_key[4:6]}-{date_key[6:8]}"] = float(level)
                    if close_map:
                        return close_map
        except Exception:
            pass

    symbol = str((STRATEGY_INDEXES.get(index_key) or {}).get("symbol") or "").strip()
    if not symbol:
        return {}
    try:
        frame = load_strategy_price_frame(symbol, start_date, end_date)
        return close_map_from_frame(frame, close_col_hint="Close")
    except Exception:
        if index_key == "NDX100":
            try:
                frame = load_strategy_price_frame("QQQ", start_date, end_date)
                return close_map_from_frame(frame, close_col_hint="Close")
            except Exception:
                return {}
        return {}


