def fetch_applyhome_apt_rows(api_key: str, recent_days: int = 120, page_size: int = 100, max_pages: int = 40) -> list[dict[str, Any]]:
    cutoff_date = date.today() - timedelta(days=max(1, recent_days))
    rows: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    total_pages = max_pages
    for page in range(1, max_pages + 1):
        payload = applyhome_get_json(
            "/ApplyhomeInfoDetailSvc/v1/getAPTLttotPblancDetail",
            {
                "page": page,
                "perPage": page_size,
                "cond[HOUSE_SECD::EQ]": "01",
                "cond[RCRIT_PBLANC_DE::GTE]": cutoff_date.isoformat(),
            },
            api_key=api_key,
        )
        if page == 1:
            try:
                total_count = int(payload.get("totalCount") or 0)
            except Exception:
                total_count = 0
            if total_count > 0:
                total_pages = min(max_pages, max(1, math.ceil(total_count / page_size)))
        page_rows = payload.get("data") if isinstance(payload.get("data"), list) else []
        if not page_rows:
            break
        for row in page_rows:
            if not isinstance(row, dict):
                continue
            if not applyhome_is_capital_area(row):
                continue
            announce_date = applyhome_parse_date(row.get("RCRIT_PBLANC_DE"))
            if announce_date and announce_date < cutoff_date:
                continue
            house_manage_no = str(row.get("HOUSE_MANAGE_NO") or "").strip()
            pblanc_no = str(row.get("PBLANC_NO") or "").strip()
            dedupe_key = house_manage_no + ":" + pblanc_no
            if not house_manage_no or not pblanc_no or dedupe_key in seen_keys:
                continue
            seen_keys.add(dedupe_key)
            rows.append(row)
        if page >= total_pages:
            break
    rows.sort(
        key=lambda item: (
            str(item.get("RCEPT_BGNDE") or ""),
            str(item.get("RCRIT_PBLANC_DE") or ""),
            str(item.get("HOUSE_NM") or ""),
        ),
        reverse=True,
    )
    return rows


