def fetch_complex_info_rows(api_key: str, address: str) -> list[dict[str, Any]]:
    text = str(address or "").strip()
    if not text:
        return []
    queries = [text]
    parts = [part for part in text.split() if part]
    if len(parts) >= 3:
        queries.append(" ".join(parts[:3]))
    if len(parts) >= 2:
        queries.append(" ".join(parts[:2]))
    seen: set[str] = set()
    rows: list[dict[str, Any]] = []
    for query in queries:
        query = query.strip()
        if not query or query in seen:
            continue
        seen.add(query)
        payload = applyhome_get_json(
            "/AptIdInfoSvc/v1/getAptInfo",
            {
                "page": 1,
                "perPage": 100,
                "cond[ADRES::LIKE]": query,
            },
            api_key=api_key,
        )
        data = payload.get("data") if isinstance(payload.get("data"), list) else []
        rows.extend(row for row in data if isinstance(row, dict))
        if rows:
            break
    return rows


