class KrxIssueStatusReader(PykrxKrxWebIo if PykrxKrxWebIo is not None else object):
    def __init__(self, bld: str):
        if PykrxKrxWebIo is None:
            raise RuntimeError("pykrx KRX Web IOÎ•??¨Ïö©?????ÜÏäµ?àÎã§.")
