def load_strategy_transition_statistics(
    market: str,
    start_date: str | None,
    end_date: str | None,
) -> dict[str, Any]:
    market_key = str(market or "kr").strip().lower()
    db_path = US_SCREENING_FAST_DB_PATH if market_key == "us" else SCREENING_FAST_DB_PATH
    if not db_path.exists():
        return {
            "market": market_key,
            "event_count": 0,
            "reached_52w_count": 0,
            "reached_52w_rate_pct": None,
            "dropout_count": 0,
            "dropout_rate_pct": None,
            "avg_return_to_52w_pct": None,
            "median_return_to_52w_pct": None,
            "avg_days_to_52w": None,
            "same_day_52w_count": 0,
            "examples": [],
        }
    start_dt = safe_strategy_date(start_date, date(2020, 1, 1))
    end_dt = safe_strategy_date(end_date, date(2026, 7, 25))
    if start_dt > end_dt:
        start_dt, end_dt = end_dt, start_dt
    with sqlite3.connect(str(db_path)) as conn:
        screening_columns = {
            str(row[1])
            for row in conn.execute("PRAGMA table_info(screening_rows)").fetchall()
            if row and len(row) > 1
        }
        close_columns = {
            str(row[1])
            for row in conn.execute("PRAGMA table_info(daily_close_cache)").fetchall()
            if row and len(row) > 1
        }
        is_20d_high_select = "r.is_20d_high" if "is_20d_high" in screening_columns else "0 AS is_20d_high"
        is_52w_high_select = "r.is_52w_high" if "is_52w_high" in screening_columns else "0 AS is_52w_high"
        close_select = "c.close_price" if "close_price" in close_columns else "NULL AS close_price"
        query = f"""
            SELECT
                r.file_date,
                r.file_date_key,
                r.stock_code,
                r.stock_name,
                {is_20d_high_select},
                {is_52w_high_select},
                {close_select}
            FROM screening_rows r
            LEFT JOIN daily_close_cache c
              ON c.file_date_key = r.file_date_key
             AND c.stock_code = r.stock_code
            WHERE r.file_date_key BETWEEN ? AND ?
            ORDER BY r.stock_code ASC, r.file_date_key ASC
        """
        frame = pd.read_sql_query(
            query,
            conn,
            params=[start_dt.strftime("%Y%m%d"), end_dt.strftime("%Y%m%d")],
        )
    if frame.empty:
        return {
            "market": market_key,
            "event_count": 0,
            "reached_52w_count": 0,
            "reached_52w_rate_pct": None,
            "dropout_count": 0,
            "dropout_rate_pct": None,
            "avg_return_to_52w_pct": None,
            "median_return_to_52w_pct": None,
            "avg_days_to_52w": None,
            "same_day_52w_count": 0,
            "examples": [],
        }
    frame["is_20d_high"] = pd.to_numeric(frame["is_20d_high"], errors="coerce").fillna(0).astype(int)
    frame["is_52w_high"] = pd.to_numeric(frame["is_52w_high"], errors="coerce").fillna(0).astype(int)
    frame["close_price"] = pd.to_numeric(frame["close_price"], errors="coerce")

    event_count = 0
    reached_52w_count = 0
    same_day_52w_count = 0
    returns_to_52w: list[float] = []
    days_to_52w: list[int] = []
    examples: list[dict[str, Any]] = []
    for _stock_code, group in frame.groupby("stock_code", sort=False):
        rows = group.to_dict("records")
        previous_20d_high = 0
        for index_no, row in enumerate(rows):
            current_20d_high = int(row.get("is_20d_high") or 0)
            if current_20d_high != 1 or previous_20d_high == 1:
                previous_20d_high = current_20d_high
                continue
            previous_20d_high = current_20d_high
            event_count += 1
            event_date_text = str(row.get("file_date") or "")
            event_date = safe_strategy_date(event_date_text, start_dt)
            event_close = to_float(row.get("close_price"))
            reached_row = None
            for future_row in rows[index_no:]:
                if int(future_row.get("is_52w_high") or 0) == 1:
                    reached_row = future_row
                    break
            if not reached_row:
                continue
            reached_52w_count += 1
            reached_date_text = str(reached_row.get("file_date") or "")
            reached_date = safe_strategy_date(reached_date_text, event_date)
            if reached_date_text == event_date_text:
                same_day_52w_count += 1
            reached_close = to_float(reached_row.get("close_price"))
            day_gap = max(0, (reached_date - event_date).days)
            days_to_52w.append(day_gap)
            return_pct = None
            if event_close not in (None, 0) and reached_close not in (None, 0):
                return_pct = ((float(reached_close) / float(event_close)) - 1.0) * 100.0
                returns_to_52w.append(return_pct)
            if len(examples) < 8:
                examples.append(
                    {
                        "stock_code": str(row.get("stock_code") or ""),
                        "stock_name": str(row.get("stock_name") or ""),
                        "event_date": event_date_text,
                        "reached_52w_date": reached_date_text,
                        "days_to_52w": day_gap,
                        "return_to_52w_pct": round(float(return_pct), 2) if return_pct is not None else None,
                    }
                )
    dropout_count = max(0, event_count - reached_52w_count)
    return {
        "market": market_key,
        "event_count": int(event_count),
        "reached_52w_count": int(reached_52w_count),
        "reached_52w_rate_pct": round((reached_52w_count / event_count) * 100.0, 2) if event_count else None,
        "dropout_count": int(dropout_count),
        "dropout_rate_pct": round((dropout_count / event_count) * 100.0, 2) if event_count else None,
        "avg_return_to_52w_pct": round(float(np.mean(returns_to_52w)), 2) if returns_to_52w else None,
        "median_return_to_52w_pct": round(float(np.median(returns_to_52w)), 2) if returns_to_52w else None,
        "avg_days_to_52w": round(float(np.mean(days_to_52w)), 1) if days_to_52w else None,
        "same_day_52w_count": int(same_day_52w_count),
        "examples": examples,
    }


def request_gemini_strategy_backtest_chat(context_payload: dict[str, Any], question: str) -> dict[str, Any]:
    api_key = get_gemini_api_key()
    if not api_key:
        raise RuntimeError("GEMINI_API_KEYÍ∞Ä ?§Ï†ï?òÏñ¥ ?àÏ? ?äÏäµ?àÎã§.")
    system_prompt = (
        "You are a quantitative strategy review assistant. "
        "Return concise Korean JSON only. "
        "Use only the provided backtest context and statistics. "
        "Be explicit about uncertainty and avoid unsupported certainty."
    )
    user_prompt = (
        "?§Ïùå Î∞±ÌÖå?§Ìä∏ Í≤∞Í≥º?Ä Î≥¥Ï°∞ ?µÍ≥ÑÎ•?Î∞îÌÉï?ºÎ°ú ÏßàÎ¨∏???µÌïò?∏Ïöî.\n"
        "Î∞òÎìú??JSONÎß?Î∞òÌôò?òÏÑ∏?? ÏΩîÎìú?úÏä§ Í∏àÏ?.\n"
        "JSON ?§ÌÇ§Îß?\n"
        "{\n"
        '  "answer": "string",\n'
        '  "bullet_points": ["string"],\n'
        '  "suggested_questions": ["string"]\n'
        "}\n"
        "Í∑úÏπô:\n"
        "- answer??4~8Î¨∏Ïû•\n"
        "- bullet_points??2~6Í∞?n"
        "- ?òÏπòÍ∞Ä ?àÏúºÎ©??∞ÏÑ† ?¨Ïö©\n"
        "- Î™®Î•¥Î©?Î∂ÄÏ°±Ìïú ?∞Ïù¥?∞ÎùºÍ≥?Î™ÖÏãú\n"
        f"ÏßàÎ¨∏: {str(question or '').strip()}\n"
        f"Ïª®ÌÖç?§Ìä∏: {json.dumps(context_payload, ensure_ascii=False)}"
    )
    model_candidates = [
        str(os.getenv("GEMINI_STRATEGY_CHAT_MODEL", "")).strip(),
        "gemini-2.5-flash",
        "gemini-2.5-flash-lite",
        "gemini-2.0-flash",
    ]
    tried_errors: list[str] = []
    for model_name in [item for item in model_candidates if item]:
        try:
            response = requests.post(
                f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}",
                headers={"Content-Type": "application/json"},
                json={
                    "systemInstruction": {"parts": [{"text": system_prompt}]},
                    "contents": [{"role": "user", "parts": [{"text": user_prompt}]}],
                    "generationConfig": {
                        "temperature": 0.25,
                        "responseMimeType": "application/json",
                    },
                },
                timeout=90,
            )
            response.raise_for_status()
            payload = response.json()
            candidates = payload.get("candidates") or []
            first = candidates[0] if candidates else {}
            parts = (((first.get("content") or {}).get("parts")) or [])
            content = "\n".join(str(part.get("text") or "").strip() for part in parts if isinstance(part, dict)).strip()
            if not content:
                raise RuntimeError("Gemini ?ëÎãµ Î≥∏Î¨∏??ÎπÑÏñ¥ ?àÏäµ?àÎã§.")
            if content.startswith("```"):
                content = re.sub(r"^```(?:json)?\s*", "", content.strip(), flags=re.IGNORECASE)
                content = re.sub(r"\s*```$", "", content.strip())
            parsed = json.loads(content)
            return {
                "answer": str((parsed or {}).get("answer") or "").strip(),
                "bullet_points": [str(item).strip() for item in ((parsed or {}).get("bullet_points") or []) if str(item).strip()][:6],
                "suggested_questions": [str(item).strip() for item in ((parsed or {}).get("suggested_questions") or []) if str(item).strip()][:4],
                "model": model_name,
                "generated_at": datetime.now().isoformat(timespec="seconds"),
            }
        except Exception as exc:
            tried_errors.append(f"{model_name}: {exc}")
            continue
    raise RuntimeError(" / ".join(tried_errors) if tried_errors else "Gemini ?ÑÎûµ ?¥ÏÑ§ ?ùÏÑ± ?§Ìå®")


def build_strategy_backtest_ai_context(request: StrategyBacktestAiChatRequest) -> dict[str, Any]:
    market_key = str(request.market or "kr").strip().lower()
    payload = request.payload if isinstance(request.payload, dict) else {}
    query = request.query if isinstance(request.query, dict) else {}
    summary = payload.get("summary") if isinstance(payload.get("summary"), dict) else {}
    rows = payload.get("rows") if isinstance(payload.get("rows"), list) else []
    signals = payload.get("signals") if isinstance(payload.get("signals"), list) else []
    recent_rows = []
    for row in rows[-40:]:
        if not isinstance(row, dict):
            continue
        recent_rows.append(
            {
                "date": str(row.get("date") or ""),
                "strategy_return_pct": to_float(row.get("strategy_return_pct")),
                "benchmark_return_pct": to_float(row.get("benchmark_return_pct")),
                "holdings_count": int(to_float(row.get("holdings_count")) or 0),
                "exposure_pct": to_float(row.get("exposure_pct")),
                "signal_reason": str(row.get("signal_reason") or ""),
            }
        )
    recent_signals = []
    for item in signals[-20:]:
        if not isinstance(item, dict):
            continue
        recent_signals.append(
            {
                "date": str(item.get("date") or ""),
                "type": str(item.get("type") or ""),
                "reason": str(item.get("reason") or ""),
                "strategy_return_pct": to_float(item.get("strategy_return_pct")),
            }
        )
    transition_stats = load_strategy_transition_statistics(
        market=market_key,
        start_date=str(payload.get("start_date") or query.get("start") or ""),
        end_date=str(payload.get("end_date") or query.get("end") or ""),
    )
    return {
        "market": market_key,
        "strategy_name": str(payload.get("strategy_name") or ""),
        "index_name": str(payload.get("index_name") or ""),
        "start_date": str(payload.get("start_date") or query.get("start") or ""),
        "end_date": str(payload.get("end_date") or query.get("end") or ""),
        "query": {
            "top_n": query.get("top_n"),
            "exit_top_n": query.get("exit_top_n"),
            "entry_threshold": query.get("entry_threshold"),
            "exit_threshold": query.get("exit_threshold"),
            "allocation_mode": query.get("allocation_mode"),
            "entry_streak_days": query.get("entry_streak_days"),
            "entry_high_filter": query.get("entry_high_filter"),
            "stop_loss_mode": query.get("stop_loss_mode"),
            "stop_loss_pct": query.get("stop_loss_pct"),
            "exit_ma20_break": query.get("exit_ma20_break"),
            "exit_ma60_break": query.get("exit_ma60_break"),
            "runup_lookback_days": query.get("runup_lookback_days"),
            "runup_exclude_pct": query.get("runup_exclude_pct"),
            "min_market_cap_100m": query.get("min_market_cap_100m"),
        },
        "summary": {
            "index_return_pct": to_float(summary.get("index_return_pct")),
            "strategy_return_pct": to_float(summary.get("strategy_return_pct")),
            "excess_return_pct": to_float(summary.get("excess_return_pct")),
            "mdd_pct": to_float(summary.get("mdd_pct")),
            "win_rate_pct": to_float(summary.get("win_rate_pct")),
            "sell_count": int(to_float(summary.get("sell_count")) or 0),
            "winning_sell_count": int(to_float(summary.get("winning_sell_count")) or 0),
            "avg_sell_return_pct": to_float(summary.get("avg_sell_return_pct")),
            "avg_winning_sell_return_pct": to_float(summary.get("avg_winning_sell_return_pct")),
            "avg_losing_sell_return_pct": to_float(summary.get("avg_losing_sell_return_pct")),
            "avg_holdings_count": to_float(summary.get("avg_holdings_count")),
            "total_fee_pct_points": to_float(summary.get("total_fee_pct_points")),
        },
        "recent_rows": recent_rows,
        "recent_signals": recent_signals,
        "transition_stats": transition_stats,
    }


@app.post("/api/strategy/backtest/ai-chat")
def strategy_backtest_ai_chat(request: StrategyBacktestAiChatRequest) -> JSONResponse:
    try:
        question = str(request.question or "").strip()
        if not question:
            return JSONResponse({"error": "ÏßàÎ¨∏??ÎπÑÏñ¥ ?àÏäµ?àÎã§."}, status_code=400)
        context_payload = build_strategy_backtest_ai_context(request)
        result = request_gemini_strategy_backtest_chat(context_payload, question)
        return JSONResponse(
            {
                "ok": True,
                "question": question,
                "context": {
                    "market": context_payload.get("market"),
                    "strategy_name": context_payload.get("strategy_name"),
                    "index_name": context_payload.get("index_name"),
                    "start_date": context_payload.get("start_date"),
                    "end_date": context_payload.get("end_date"),
                    "transition_stats": context_payload.get("transition_stats") or {},
                },
                "result": result,
            }
        )
    except Exception as exc:
        return JSONResponse({"error": str(exc)}, status_code=500)


