def _normalize_score_formula_sync_markets(markets: list[str] | None) -> list[str]:
    allowed = {"kr", "us", "asia"}
    normalized: list[str] = []
    for market in markets or ["kr"]:
        value = str(market or "").strip().lower()
        if value in allowed and value not in normalized:
            normalized.append(value)
    return normalized or ["kr"]


def _oracle_score_formula_sync_token() -> str:
    return str(os.getenv("ORACLE_SCORE_SYNC_TOKEN") or os.getenv("STOCK_ORACLE_SYNC_TOKEN") or "").strip()


def _oracle_stock_app_url() -> str:
    return str(os.getenv("ORACLE_STOCK_APP_URL") or os.getenv("STOCK_ORACLE_APP_URL") or "").strip().rstrip("/")


@app.post("/api/oracle-sync/score-formula/apply")
def oracle_score_formula_sync_apply(
    request: OracleScoreFormulaSyncApplyRequest,
    x_oracle_sync_token: str | None = Header(default=None),
) -> JSONResponse:
    try:
        expected_token = _oracle_score_formula_sync_token()
        if expected_token and str(x_oracle_sync_token or "").strip() != expected_token:
            return JSONResponse({"error": "?ôÍ∏∞???†ÌÅ∞???¨Î∞îÎ•¥Ï? ?äÏäµ?àÎã§."}, status_code=403)
        if not expected_token:
            return JSONResponse({"error": "ORACLE_SCORE_SYNC_TOKEN???úÎ≤Ñ???§Ï†ï?òÏñ¥ ?àÏ? ?äÏäµ?àÎã§."}, status_code=500)
        saved: dict[str, Any] = {}
        for market in _normalize_score_formula_sync_markets(list((request.configs or {}).keys())):
            incoming = request.configs.get(market)
            if not isinstance(incoming, dict):
                continue
            existing = load_score_formula_config(market)
            saved[market] = save_score_formula_config(merge_score_formula_config(existing, incoming), market)
        invalidate_screening_runtime_caches()
        return JSONResponse({"ok": True, "saved_markets": list(saved.keys()), "configs": saved})
    except Exception as exc:
        return JSONResponse({"error": str(exc)}, status_code=500)


@app.post("/api/oracle-sync/score-formula/push")
def oracle_score_formula_sync_push(request: OracleScoreFormulaSyncPushRequest) -> JSONResponse:
    try:
        target_url = str(request.target_url or "").strip().rstrip("/") or _oracle_stock_app_url()
        token = _oracle_score_formula_sync_token()
        if not target_url:
            return JSONResponse({"error": "ORACLE_STOCK_APP_URL???§Ï†ï?òÏñ¥ ?àÏ? ?äÏäµ?àÎã§."}, status_code=400)
        if not token:
            return JSONResponse({"error": "ORACLE_SCORE_SYNC_TOKEN???§Ï†ï?òÏñ¥ ?àÏ? ?äÏäµ?àÎã§."}, status_code=400)
        markets = _normalize_score_formula_sync_markets(request.markets)
        configs = {market: load_score_formula_config(market) for market in markets}
        response = requests.post(
            target_url + "/api/oracle-sync/score-formula/apply",
            json={"configs": configs},
            headers={"X-Oracle-Sync-Token": token},
            timeout=60,
        )
        response.raise_for_status()
        payload = response.json()
        if isinstance(payload, dict) and payload.get("error"):
            raise RuntimeError(str(payload.get("error")))
        return JSONResponse({
            "ok": True,
            "target_url": target_url,
            "markets": markets,
            "remote": payload,
        })
    except Exception as exc:
        return JSONResponse({"error": str(exc)}, status_code=500)


